create table if not exists users (user_id varchar(36) not null, login varchar(128) collate utf8_unicode_ci not null, alias varchar(128) collate utf8_unicode_ci not null, pw_hash varchar(256) collate utf8_unicode_ci not null, regDate datetime not null, avatar varchar(512) collate utf8_unicode_ci, birthDay date, blackList BOOLEAN not null, followed_by varchar(36), pref_lang varchar(16) not null, primary key (user_id)) ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
